entries[62476] = { ["name"] = "Gefräßiger Schlitzer", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n3 - 8 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\nBenötigt Wächter von Baradin\n- Respektvoll\nVerkaufspreis:" }
entries[62477] = { ["name"] = "Heimtückischer Stab", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\nBenötigt Wächter von Baradin\n- Respektvoll\nVerkaufspreis:" }
entries[62478] = { ["name"] = "Schimmernder Morgenstern", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+12 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 2 Vielseitigkeit\nHaltbarkeit 90 / 90\nBenötigt Wächter von Baradin\n- Respektvoll\nVerkaufspreis:" }
entries[62479] = { ["name"] = "Himmelsdurchbohrer", ["text"] = "Wird beim Aufheben gebunden\nDistanz Armbrust\n7 - 11 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 80 / 80\nBenötigt Wächter von Baradin\n- Respektvoll\nVerkaufspreis:" }
