entries[62543] = { ["name"] = "Aprikas Puppe", ["text"] = "Questgegenstand\n\"Manchmal ist es schwer, loszulassen.\"" }
entries[62544] = { ["name"] = "Fleisch der Staubspeier", ["text"] = "Questgegenstand\n\"Das solltet Ihr vielleicht erst einmal abwischen...\"" }
entries[62545] = { ["name"] = "Mearas Trockenrosen", ["text"] = "Questgegenstand\n\"Mit dem vertrauten Duft von Zuhause.\"" }
entries[62546] = { ["name"] = "Parlans Elfenbeinhammer", ["text"] = "Questgegenstand\n\"Wird seit Jahren von Generation zu Generation weitergereicht.\"" }
entries[62547] = { ["name"] = "Seide der Staubspeier", ["text"] = "Questgegenstand\n\"Vermutlich zur Herstellung von Lendenschurzen.\"" }
entries[62548] = { ["name"] = "Banner der Gefallenen", ["text"] = "Questgegenstand\nBenutzen: Markiert einen gefallenen Orc mit den Farben von Orgrimmar, sodass er nach der Schlacht geborgen wird." }
entries[62549] = { ["name"] = "Verkohltes Fleisch", ["text"] = "Verkaufspreis:" }
entries[62550] = { ["name"] = "Gebetsblume", ["text"] = "Questgegenstand\n\"Diese Blumen wachsen in Richtung Himmel, selbst im dunkelsten Schatten.\"" }
entries[62551] = { ["name"] = "Intaktes Stagalsumpfnatternherz", ["text"] = "Questgegenstand" }
entries[62552] = { ["name"] = "Glückskarte", ["text"] = "\"Vielleicht habt Ihr mit einer anderen Weissagung mehr Glück.\"\nVerkaufspreis:" }
entries[62553] = { ["name"] = "Glückskarte", ["text"] = "\"Haltet Euch von eigenartigem Fleisch fern.\"\nVerkaufspreis:" }
entries[62554] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr hättet diese Spinne wirklich plündern sollen.\"\nVerkaufspreis:" }
entries[62555] = { ["name"] = "Glückskarte", ["text"] = "\"Traut niemals einem ehrlichen Goblin oder einem nüchternen Zwerg.\"\nVerkaufspreis:" }
entries[62556] = { ["name"] = "Glückskarte", ["text"] = "\"Man weiß es nie genau, bis man plündert.\"\nVerkaufspreis:" }
entries[62557] = { ["name"] = "Glückskarte", ["text"] = "\"Es wird Regen geben.\"\nVerkaufspreis:" }
entries[62558] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr werdet das Klimpern goldener Münzen hören.\"\nVerkaufspreis:" }
entries[62559] = { ["name"] = "Glückskarte", ["text"] = "\"Vertraut auf das Licht, aber behaltet Euer Reittier im Auge.\"\nVerkaufspreis:" }
entries[62560] = { ["name"] = "Glückskarte", ["text"] = "\"Steht nie im Schatten von Drachen.\"\nVerkaufspreis:" }
entries[62561] = { ["name"] = "Glückskarte", ["text"] = "\"Der Weg zum Schwarzfels ist mit guten Absichten gepflastert.\"\nVerkaufspreis:" }
entries[62562] = { ["name"] = "Glückskarte", ["text"] = "\"Viele Schlachtzugwipes liegen in nächster Zukunft.\"\nVerkaufspreis:" }
entries[62563] = { ["name"] = "Glückskarte", ["text"] = "\"Epics sind wie Kinder: die der anderen sind nie so wundervoll wie Eure.\"\nVerkaufspreis:" }
entries[62564] = { ["name"] = "Glückskarte", ["text"] = "\"Erfahrung, Ehrenpunkte und Fraktionsruf liegen in den kommenden Tagen vor Euch.\"\nVerkaufspreis:" }
entries[62565] = { ["name"] = "Glückskarte", ["text"] = "\"Euer größtes Glück sind die Freunde, die Ihr habt. Besonders Tanks.\"\nVerkaufspreis:" }
entries[62566] = { ["name"] = "Glückskarte", ["text"] = "\"Die Zukunft sieht kataklysmisch aus.\"\nVerkaufspreis:" }
entries[62567] = { ["name"] = "Glückskarte", ["text"] = "\"Entdeckt die Schönheit des Gewöhnlichen. Und dann verkauft es für Bares an einen Händler.\"\nVerkaufspreis:" }
entries[62568] = { ["name"] = "Glückskarte", ["text"] = "\"Wer ein Blind Date verspricht, ist beim Aufreißen gebunden.\"\nVerkaufspreis:" }
entries[62569] = { ["name"] = "Glückskarte", ["text"] = "\"Der Segen eines Schamanen ist elementar.\"\nVerkaufspreis:" }
entries[62570] = { ["name"] = "Glückskarte", ["text"] = "\"Eure Zukunft sieht rosig aus. Außer Ihr lauft Todesschwinge über den Weg.\"\nVerkaufspreis:" }
entries[62571] = { ["name"] = "Glückskarte", ["text"] = "\"Eure Chancen, in naher Zukunft eine 100 zu würfeln, stehen nicht schlecht.\"\nVerkaufspreis:" }
entries[62572] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr werdet beim Angeln ein tiefes Gefühl von Entspannung (und Geduld) empfinden.\"\nVerkaufspreis:" }
entries[62573] = { ["name"] = "Glückskarte", ["text"] = "\"Eines Tages werdet Ihr Euch dieses Reittier leisten können.\"\nVerkaufspreis:" }
entries[62574] = { ["name"] = "Glückskarte", ["text"] = "\"ZEIT, NACHZUBESTELLEN! Um mehr Weissagungen zu erhalten, schreibt an F.B. Krazzlestix, Bilgewässer Hafen. Mengenrabatte sind zu günstigen Konditionen erhältlich.\"\nVerkaufspreis:" }
entries[62575] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr habt viele verborgene Talente. Mit mehr Erfahrung werdet Ihr noch mehr hinzugewinnen.\"\nVerkaufspreis:" }
entries[62576] = { ["name"] = "Glückskarte", ["text"] = "\"Wer eine ganze Armee bekämpft, ist ein Märtyrer; Wer gegen fünf auf einmal kämpft, ist die Elite.\"\nVerkaufspreis:" }
entries[62577] = { ["name"] = "Glückskarte", ["text"] = "\"Ein leichtes Herz trägt Euch durch schlechte Schlachtfelder.\"\nVerkaufspreis:" }
entries[62578] = { ["name"] = "Glückskarte", ["text"] = "\"All Eure Mühen sind die Reparaturkosten wert.\"\nVerkaufspreis:" }
entries[62579] = { ["name"] = "Glückskarte", ["text"] = "\"Vertraut niemals einem Troll. Und auch keinem Schurken. Besonders keinem Trollschurken.\"\nVerkaufspreis:" }
entries[62580] = { ["name"] = "Glückskarte", ["text"] = "\"Ungläubigkeit zerstört die Magie.\"\nVerkaufspreis:" }
entries[62581] = { ["name"] = "Glückskarte", ["text"] = "\"Die Gelegenheit ist günstig, etwas neues zu probieren. Vielleicht einen neuen Beruf.\"\nVerkaufspreis:" }
entries[62582] = { ["name"] = "Glückskarte", ["text"] = "\"Jede Pflanze blüht dann auf, wenn die Zeit reif ist. Und dann pflückt Ihr sie!\"\nVerkaufspreis:" }
entries[62583] = { ["name"] = "Glückskarte", ["text"] = "\"Geht und ruht Euch aus. Ihr habt es Euch verdient. Aber vergesst nicht, in einem Gasthaus auszuruhen!\"\nVerkaufspreis:" }
entries[62584] = { ["name"] = "Glückskarte", ["text"] = "\"Wer einen Wipe erwartet, wird nie enttäuscht.\"\nVerkaufspreis:" }
entries[62585] = { ["name"] = "Glückskarte", ["text"] = "\"Seht niemals nach oben, wenn fliegende Reittiere über Euch sind.\"\nVerkaufspreis:" }
entries[62586] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr werdet eine große Summe Geld erben. Ihr werdet alles im Auktionshaus verpulvern.\"\nVerkaufspreis:" }
entries[62587] = { ["name"] = "Glückskarte", ["text"] = "\"Jemand in Eurem näheren Umkreis möchte mit Euch /flirten.\"\nVerkaufspreis:" }
entries[62588] = { ["name"] = "Glückskarte", ["text"] = "\"Eure Talente werden anerkannt und belohnt. Wenn Eure Talentverteilung gut ist, natürlich.\"\nVerkaufspreis:" }
entries[62589] = { ["name"] = "Glückskarte", ["text"] = "\"Hilfe! Ich werde in einer Glückskeksfabrik gefangengehalten!\"\nVerkaufspreis:" }
entries[62590] = { ["name"] = "Glückskarte", ["text"] = "\"Morgen wird die Sonne scheinen.\"\nVerkaufspreis:" }
entries[62591] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr werdet ein Geschenk von jemandem erhalten, den Ihr verabscheut.\"\nVerkaufspreis:" }
entries[62592] = { ["name"] = "Verkohlte Hochlandbirke", ["text"] = "Questgegenstand\n\"Dieses verbrannte Holz verströmt einen unverwechselbaren Geruch. Kein Wunder, dass die Greifen so leicht darauf reagieren.\"" }
entries[62593] = { ["name"] = "Kräftiger Schlick", ["text"] = "Questgegenstand\n\"Die Probe hört nicht auf, sich zu verschieben und zu bewegen.\"" }
entries[62594] = { ["name"] = "Zerbrochener Kelch", ["text"] = "Questgegenstand\n\"Anscheinend sind hier Edelsteine aus Ihren Fassungen gebrochen worden.\"" }
entries[62595] = { ["name"] = "Staubige Vase", ["text"] = "Questgegenstand\n\"Rissig, abgeschlagen und alt.\"" }
entries[62596] = { ["name"] = "Irdene Hieroglyphe", ["text"] = "Questgegenstand\n\"Ein uraltes Wort in einer vergessenen Sprache, in den Stein gekerbt.\"" }
entries[62597] = { ["name"] = "Troggwerkzeug", ["text"] = "Questgegenstand\n\"Ein Stein.\"" }
entries[62598] = { ["name"] = "Glückskarte", ["text"] = "\"Der Beginn aller Weisheit ist das Verlangen nach ihr. Der Weisheit letzter Schluss ist Theorycrafting.\"\nVerkaufspreis:" }
entries[62599] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr werdet ein langes, glückliches Leben mit vielen Wiederbelebungen darin haben.\"\nVerkaufspreis:" }
entries[62600] = { ["name"] = "Glückskarte", ["text"] = "\"Der Weg des Facerollers ist nicht der Weg des Weisen.\"\nVerkaufspreis:" }
entries[62601] = { ["name"] = "Glückskarte", ["text"] = "\"Es ist nicht alles Gold, was glänzt. Aber meistens könnt Ihr es für Gold verkaufen.\"\nVerkaufspreis:" }
entries[62602] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr teilt gern Eure Weisheit. Wenn Ihr so weitermacht, bleibt Euch nicht viel.\"\nVerkaufspreis:" }
entries[62603] = { ["name"] = "Glückskarte", ["text"] = "\"Wenn das Leben Euch Zitronen gibt, bezahlt die Reparaturkosten.\"\nVerkaufspreis:" }
entries[62604] = { ["name"] = "Glückskarte", ["text"] = "\"Die Feder in der Hand ist besser als der Windreiter auf dem Dach.\"\nVerkaufspreis:" }
entries[62605] = { ["name"] = "Glückskarte", ["text"] = "\"Eure Glückszahlen sind: 4 8 15 16 23 42\"\nVerkaufspreis:" }
entries[62606] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr habt viele Freunde und sehr wenige Feinde, die am Leben sind.\"\nVerkaufspreis:" }
entries[62607] = { ["name"] = "Aktivierungsgerät der Titanen", ["text"] = "Questgegenstand\n\"Das Ganze ist größer als die Summe seiner Teile.\"" }
entries[62608] = { ["name"] = "Schlüsselcode für Truhe aus Uldum", ["text"] = "Questgegenstand\nBenutzen: Öffnet eine Kiste oder Truhe." }
entries[62609] = { ["name"] = "Reinquellpartikel", ["text"] = "Questgegenstand\n\"Es ist völlig durchsichtig und fühlt sich kühl an.\"" }
entries[62610] = { ["name"] = "Gerätekomponente der Titanen", ["text"] = "Questgegenstand\nBenutzen: Kombiniert 6 Gerätekomponenten der Titanen um das Aktivierungsgerät der Titanen herzustellen. (3 Sek. Abklingzeit)" }
entries[62611] = { ["name"] = "Aktivierungsgerät der Titanen", ["text"] = "Questgegenstand\nBenutzen: Erweckt den titanischen Wächter in der Kammer der Sonne. (3 Sek. Abklingzeit)" }
entries[62621] = { ["name"] = "Wartungsaxt", ["text"] = "Questgegenstand" }
entries[62649] = { ["name"] = "Glückskeks", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 640 * 30 / 5) Gesundheit und ( 640 / 5 * 30) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 15 Ausdauer und ein für Euch nützlicher Wert wird um 15 erhöht.\nVerkaufspreis:" }
entries[62650] = { ["name"] = "Dunkeleisenkopf", ["text"] = "Questgegenstand\n\"Der Bart ist erstaunlich gut als Griff geeignet.\"" }
entries[62651] = { ["name"] = "Leicht angebratener Lauerer", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 450 * 30 / 5) Gesundheit und ( 300 / 5 * 30) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 6 kritischen Trefferwert und 6 Ausdauer.\nVerkaufspreis:" }
