entries[62900] = { ["name"] = "Zügel des Vulkansteindrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Vulkansteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Feuer kann Stein auf faszinierende Art verändern, doch erzählt der Steinmutter nicht, dass ich das gesagt habe.\" - Erdenruferin Yevaa\nErfolg:\nHeldenruhm des Kataklysmus\nKategorie:\nDungeons & Schlachtzüge" }
entries[62901] = { ["name"] = "Zügel des Drachen des Ostwinds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachen des Ostwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bei all seinen wahnsinnigen Bemühungen, neue Drachen zu erschaffen, hat Todesschwinge ganz vergessen, dass es noch viele unglaubliche Rassen gibt, die wir nie in Azeroth erblickt haben.\" - Thrall\nErfolg:\nRuhm des Kataklysmus-Schlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
