entries[63039] = { ["name"] = "Zügel des Drachen des Westwinds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachen des Westwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Wächter von Baradin\n- Ehrfürchtig\n\n\"Diese majestätischen Bestien nutzen die elementaren Kräfte des Sturms, knistern wie Blitze und brüllen wie der Donner.\"\nVerkäufer:\nRüstmeister Brazie\nZone:\nHalbinsel von Tol Barad\nFraktion:\nWächter von Baradin - Ehrfürchtig" }
entries[63040] = { ["name"] = "Zügel des Drachen des Nordwinds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachen des Nordwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wer den Sturm kennt wird der Ruhe überdrüssig.\"\nBeute von:\nAltairus\nZone:\nDer Vortexgipfel" }
entries[63041] = { ["name"] = "Zügel des Drachen des Südwinds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachen des Südwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wie eine zarte Brise im Sommer. Aber das will nicht viel heißen, wenn man bedenkt, woher sie kommt. - Itesh\"\nBeute von:\nAl'Akir\nZone:\nThron der Vier Winde" }
entries[63042] = { ["name"] = "Zügel des Phosphorsteindrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Phosphorsteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Steinmutter hat sich nie viele Gedanken über den rebellischen Aeonaxx gemacht und sogar zugelassen, dass seine Brut ihr Reich verlässt.\"\nBeute von:\nAeonaxx\nOrt:\nTiefenheim" }
entries[63043] = { ["name"] = "Zügel des Vitriolsteindrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Vitriolsteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die wären perfekt für einen Anhänger geeignet, und das da würde einen fantastischen Ring ergeben. Lasst mich wissen, wenn das Ding sich häutet oder so. - Kalinda\"\nBeute von:\nPlattenhaut\nZone:\nDer Steinerne Kern" }
entries[63044] = { ["name"] = "Zügel des braunen Reitkamels", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares braunes Reitkamel oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ramkahen\n- Ehrfürchtig\n\n\"An einem einzigen Nachmittag hat Fennimore Quigley als Erster ein Kamel gemolken und kurz darauf auch noch den Rekord für den längsten unbeabsichtigten Flug gebrochen.\"\nVerkäufer:\nSchmied Abasi\nZone:\nUldum\nFraktion:\nRamkahen - Ehrfürchtig\nKosten:" }
