entries[63355] = { ["name"] = "Rostbergmöwe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure Rostbergmöwe beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Wächter von Baradin\n- Wohlwollend" }
