entries[63357] = { ["name"] = "Schwarzfelsverkleidung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verkleidet Euch als einen Diener der Schwarzfelsorcs.\n\"Eine perfekte Tarnung, mit der Ihr Euch sogar an den schärften Schwarzfelsaugen vorbeischleichen könnt. Sprecht mit Thelaron Düsternadel, um eine neue Tarnung zu bekommen, wenn Ihr diese verlegt.\"" }
entries[63358] = { ["name"] = "Horn der Rufer", ["text"] = "Questgegenstand\n\"Das können wir benutzen.\"" }
entries[63359] = { ["name"] = "Banner der Zusammenarbeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt eine Schlachtstandarte Eurer Gilde auf, die den Erfahrungs-, Ehren- und Rufgewinn aller Gildenmitglieder für das Töten von Monstern im Umkreis von 100 Metern um die Standarte um 5% erhöht. Hält 15 Min. lang an. (10 Min Abklingzeit)\nBenötigt Gilde\n- Freundlich\nVerkaufspreis:" }
entries[63374] = { ["name"] = "Bahrums Hose", ["text"] = "Questgegenstand\nEinzigartig\n\"Graviert: Bahrum.\"" }
entries[63376] = { ["name"] = "Schlachtstandarte von Höllschreis Hand", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt eine Schlachtstandarte von Höllschreis Hand auf, die über 40000 Gesundheit verfügt und den verursachten Schaden aller Gruppenmitglieder im Umkreis von 45 Metern um die Standarte um 10% erhöht. Hält 2 Min. lang an und kann nur auf Tol Barad aufgestellt werden. (10 Min Abklingzeit)\nBenötigt Höllschreis Hand\n- Respektvoll" }
entries[63377] = { ["name"] = "Schlachtstandarte der Wächter von Baradin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt eine Schlachtstandarte der Wächter von Baradin auf, die über 40000 Gesundheit verfügt und den verursachten Schaden aller Gruppenmitglieder im Umkreis von 45 Metern um die Standarte um 10% erhöht. Hält 2 Min. lang an und kann nur auf Tol Barad aufgestellt werden. (10 Min Abklingzeit)\nBenötigt Wächter von Baradin\n- Respektvoll" }
